package main

import (
	"fmt"
	"sort"
	"sync"
)

func main() {
	var mu sync.Mutex
	var got []int
	var wg sync.WaitGroup
	for _, v := range []int{1, 2, 3} {
		wg.Add(1)
		go func(v int) { // pass v in: no capture bug
			defer wg.Done()
			mu.Lock()
			got = append(got, v)
			mu.Unlock()
		}(v)
	}
	wg.Wait()
	sort.Ints(got)
	fmt.Println(got)
	// Output: [1 2 3]
}

package main

import (
	"context"
	"fmt"
)

func worker(ctx context.Context, ch <-chan int) {
	for {
		select {
		case <-ctx.Done(): // guaranteed exit path
			return
		case v := <-ch:
			_ = v
		}
	}
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	go worker(ctx, make(chan int))
	cancel() // signals the worker to return
	fmt.Println("worker will exit")
	// Output: worker will exit
}

