package main

import "fmt"

func main() {
	n := 5
	results := make(chan int, n)      // buffered so sends never block
	for i := 1; i <= n; i++ {
		go func(x int) {              // x is a per-goroutine copy of i
			results <- x * x          // send the square back to main
		}(i)
	}
	sum := 0
	for i := 0; i < n; i++ {          // receive exactly n results
		sum += <-results
	}
	fmt.Println(sum)                  // 1+4+9+16+25 = 55
}

