package solution

import "sync"

func Solve(nums []int, workers int) int {
	if workers < 1 {
		workers = 1
	}
	jobs := make(chan int, len(nums))     // buffered: senders never block
	for _, n := range nums {
		jobs <- n
	}
	close(jobs)                            // lets `range jobs` terminate

	partials := make(chan int, workers)
	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			sum := 0
			for n := range jobs {      // drain until closed & empty
				sum += n
			}
			partials <- sum
		}()
	}
	go func() { wg.Wait(); close(partials) }()  // close after all finish

	total := 0
	for p := range partials {              // addition is commutative
		total += p
	}
	return total
}

