func RunAll(tasks []func() int) []int {
	res := make([]int, len(tasks))   // pre-sized; each index written once
	var wg sync.WaitGroup
	for i, task := range tasks {
		wg.Add(1)
		go func(idx int, fn func() int) {  // copy idx & fn per goroutine
			defer wg.Done()
			res[idx] = fn()           // distinct index -> no data race
		}(i, task)
	}
	wg.Wait()
	return res
}

func FanIn(inputs []<-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup
	wg.Add(len(inputs))
	for _, in := range inputs {
		go func(ch <-chan int) {   // copy ch per goroutine
			defer wg.Done()
			for v := range ch {    // drain until this input closes
				out <- v           // forward to the merged channel
			}
		}(in)
	}
	go func() {                    // sole closer of out
		wg.Wait()                  // all forwarders finished
		close(out)                 // now safe to close
	}()
	return out
}
